script:
// Banner (ds-metrics §13 — InlineNotice / OperationNoticeBanner): style icon + message (bodyMedium, el16, fills the row),
// gap sm, padding lg × md, radius 16 (theme panel radius, no token), bg2. Icon tint: info accentPrimary, success success,
// warning warning, error errorPressed (accessibleErrorText). dismissible adds a trailing close glyph (el9); like the
// DS the whole banner is the dismiss target and emits `close`.
param title: string
param style: "info" | "success" | "warning" | "error" = "info"
param dismissible: bool = false
event close
